def verify_isbn(isbn: str) -> str:
    # Check if the input is a valid ISBN number
    if not isbn.isdigit() or len(isbn) != 13:
        raise ValueError("Invalid ISBN number")

    # Calculate the checksum digit using the ISBN standard formula
    sum = 0
    for i, digit in enumerate(isbn):
        if i % 2 == 0:
            sum += int(digit)
        else:
            sum += int(digit) * 3
    checksum = (10 - (sum % 10)) % 10

    # If the checksum is correct, return "Right"
    if checksum == isbn[-1]:
        return "Right"

    # If the checksum is incorrect, return the corrected ISBN number
    return isbn[:-1] + str(checksum)

